let SID=0;const SP={};
const spk=(txt,lang)=>{const id='s'+(++SID);SP[id]=[txt,lang||(L==='hi'?'hi-IN':'en-IN')];return `<button class="spk" data-sp="${id}">🔊 ${t('Listen','सुनें')}</button>`};
function say(id){if(!('speechSynthesis' in window))return alert(t('Speech not supported on this browser','इस ब्राउज़र में आवाज़ सपोर्ट नहीं'));const [x,lg]=SP[id];speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(x);u.lang=lg;u.rate=.92;const v=speechSynthesis.getVoices().find(v=>v.lang&&v.lang.toLowerCase().startsWith(lg.slice(0,2)));if(v)u.voice=v;speechSynthesis.speak(u)}
const store=(k,v)=>{const a=JSON.parse(localStorage.getItem(k)||'[]');if(v){a.unshift(v);localStorage.setItem(k,JSON.stringify(a))}return a};
