const V={};
V.home=()=>`<h1>${t('Explore HajCare AI','HajCare AI एक्सप्लोर करें')}</h1><p class="sub">${t('All guidance and tools for your Hajj 2027 journey.','हज 2027 के सफ़र की पूरी रहनुमाई और टूल।')}</p>
<div class="cta"><a class="btn" href="index.html#why">✨ ${t('4 main features','4 ख़ास फ़ीचर')}</a></div>`+SEC.map(s=>`<h2>${s[1]}</h2><div class="grid">`+s[2].map(i=>`<a class="tile" href="${i[0]==='library'?'library.html':'#'+i[0]}"><i>${ICO[i[0]]||i[1]}</i><b>${t(i[2],i[3])}</b></a>`).join('')+`</div>`).join('');
V.circulars=()=>`<h1>${t('Circulars — Hajj 2027','सर्कुलर — हज 2027')}</h1><div class="note">${t('Auto-update will come in the live app. In this demo, cards are samples — open the official source for the actual circulars.','ऑटो-अपडेट लाइव ऐप में आएगा। इस डेमो में कार्ड नमूना हैं — असली सर्कुलर के लिए आधिकारिक साइट खोलें।')}</div>`+CIRC.map(c=>`<div class="card">${SAMPLE}<span class="tag">${esc(c.src)}</span><h3>${esc(c.t)}</h3><p><b>${t('English original','अंग्रेज़ी मूल')}:</b> ${esc(c.s[0])}</p><p><b>${t('Summary','ख़ुलासा')}:</b> ${esc(L==='hi'?c.s[1]:c.s[0])}</p>${spk(L==='hi'?c.s[1]:c.s[0])} <a class="btn o" style="margin-left:6px;padding:5px 12px;font-size:13px" target="_blank" rel="noopener" href="${c.url}">${t('Official site','आधिकारिक साइट')} ↗</a></div>`).join('');
V.rules=()=>`<h1>${t('Saudi Rules & Conduct','सऊदी नियम और आचरण')}</h1><p class="sub">${t('General guidance. Always follow the latest official instructions.','आम रहनुमाई। हमेशा ताज़ा आधिकारिक हिदायतें मानें।')}</p>`+RULES.map((r,i)=>{const b=L==='en'?r[2]:r[3];return `<details${i?'':' open'}><summary>${i+1}. ${t(r[0],r[1])}</summary><ul>${b.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${spk(t(r[0],r[1])+'. '+b.join(' '))}</details>`}).join('');
function dayPlan(n){const a=ARKAN[(n-1)%ARKAN.length],d=DOC[(n-1)%DOC.length];return [['Quran',2,'क़ुरआन',t('Recite & reflect: short surah / ayah of the day','तिलावत और ग़ौर: आज की सूरह / आयत')],['Hadith',2,'हदीस',t('One hadith on Hajj or good character','हज या अख़लाक़ पर एक हदीस')],['Duas',2,'दुआएँ',t('Learn one masnoon dua','एक मसनून दुआ याद करें')],['Arkan',10,'अरकान',t(a[0],a[1])],['Doctor Corner',5,'डॉक्टर कॉर्नर',t(d[0],d[1])],['Naat',3,'नात',t('Listen to a naat','एक नात सुनें')],['Revision',3,'दोहराई',t('Revise yesterday','कल का दोहराएँ')],['Aage ki taiyari',3,'आगे की तैयारी',n%10===0?t('Documents & packing check','दस्तावेज़ और सामान चेक'):t('Preview tomorrow','कल की झलक')]]}
V.preparation=()=>{let h=`<h1>${t('100-Day Hajj Training','100 दिन हज ट्रेनिंग')}</h1><p class="sub">${t('30 minutes daily','रोज़ 30 मिनट')}: ${TRAIN.map(x=>`${t(x[0],x[2])} ${x[1]}`).join(' · ')}</p><div class="note">${t('Sample structure — final content will be decided under the supervision of ulama.','नमूना ढाँचा — अंतिम सामग्री उलमा-ए-किराम की निगरानी में तय होगी।')}</div>`;for(let n=1;n<=100;n++){const p=dayPlan(n);h+=`<details><summary>${t('Day','दिन')} ${n} — ${p[3][3]}</summary><table>${p.map(r=>`<tr><td>${t(r[0],r[2])}</td><td>${r[1]} ${t('min','मिनट')}</td><td>${r[3]}</td></tr>`).join('')}</table><div class="cta"><a class="btn" href="#day-${n}">📄 ${t('Day','दिन')} ${n} PDF</a>${spk(t('Day','दिन')+' '+n+'. '+p.map(r=>t(r[0],r[2])+' '+r[3]).join('. '))}</div></details>`}return h};
V.day=n=>{const p=dayPlan(n);const trailer=n===1?'<div id="day1-trailer" class="card" style="margin:18px 0"><style>#day1-trailer .d1w{display:block;width:100%;max-width:720px;margin:0 auto;background:#000;border-radius:12px}#day1-trailer .d1n{display:none;width:100%;max-width:420px;margin:0 auto;background:#000;border-radius:12px}@media (max-width:720px){#day1-trailer .d1w{display:none}#day1-trailer .d1n{display:block}}</style><h3>दिन 1 — नीयत: हज इबादत है, सैर नहीं · 30 सेकंड ट्रेलर (डेमो)</h3><p class="tag">डेमो</p><p>नमूना — आलिम और डॉक्टर की समीक्षा बाक़ी</p><video class="d1w" controls playsinline preload="metadata" src="/videos/day1-trailer-16x9.mp4"></video><video class="d1n" controls playsinline preload="metadata" src="/videos/day1-trailer-9x16.mp4"></video></div>':'';return `${trailer}<div class="noprint cta"><a class="btn o" href="#preparation">← ${t('Back','वापस')}</a><button class="btn" onclick="print()">⬇️ ${t('Save as PDF / Print','PDF सेव करें / प्रिंट')}</button></div><div class="card"><span class="tag s">${t('Sample','नमूना')}</span><h1>HajCare AI — ${t('Day','दिन')} ${n} / 100</h1><p class="sub">${t('30-minute daily Hajj training','रोज़ 30 मिनट हज ट्रेनिंग')}</p><table><tr><th>${t('Part','हिस्सा')}</th><th>${t('Time','वक़्त')}</th><th>${t('Topic','विषय')}</th></tr>${p.map(r=>`<tr><td>${t(r[0],r[2])}</td><td>${r[1]} ${t('min','मिनट')}</td><td>${r[3]}</td></tr>`).join('')}</table><p class="note">${t('Sample — final content under ulama supervision.','नमूना — अंतिम सामग्री उलमा की निगरानी में।')}</p><p style="font-size:12px">HajCare AI · SAZO Management Pvt Ltd</p></div>`};
// Guides (approved by Saiful). Mainstream content; fiqh details: ulama se confirm karein.
const GUIDE_NOTE=()=>`<div class="note">${t('Simple general guidance. For fiqh details (maslak differences, kaffarah etc.) please confirm with your ulama.','आसान आम रहनुमाई। फ़िक़्ही मसाइल (मसलक का फ़र्क़, कफ़्फ़ारा वग़ैरह) अपने उलमा से ज़रूर कन्फ़र्म करें।')}</div>`;
const GTOP=[
['Hajj guide — day by day (8–13 Dhul Hijjah)','हज गाइड — दिन-ब-दिन (8–13 ज़िलहिज्जा)',
['8 Dhul Hijjah (Yawm at-Tarwiyah): Put on ihram with the niyyah of Hajj (Tamattu pilgrims from their residence in Makkah), recite Talbiya and go to Mina. Pray Zuhr, Asr, Maghrib, Isha and next Fajr in Mina.',
'9 Dhul Hijjah (Day of Arafah): After sunrise go to Arafat. Staying in Arafat (wuquf) from after Zawal till sunset is the most important pillar of Hajj. Spend it in dua, dhikr and Talbiya.',
'Night of 10th: After sunset go to Muzdalifah (without praying Maghrib in Arafat). Pray Maghrib and Isha together, rest, collect small pebbles, and pray Fajr there.',
'10 Dhul Hijjah (Eid): Go to Mina and hit only the big Jamarah (Jamarat al-Aqabah) with 7 pebbles; stop Talbiya then. Then qurbani (for Tamattu/Qiran), then halq (shave) or taqsir (trim). Most ihram restrictions end.',
'Tawaf al-Ifadah (a pillar) and Sa\'i of Hajj: done on the 10th or in the following days (as per your scholar), then return to Mina.',
'11 and 12 Dhul Hijjah: Stay in Mina. After Zawal hit all three Jamarat in order — small, middle, big — 7 pebbles each.',
'13 Dhul Hijjah: Pilgrims who stay hit all three Jamarat again after Zawal. Those leaving on the 12th must leave Mina before sunset.',
'Before leaving Makkah for home: Tawaf al-Wida (farewell tawaf).'],
['8 ज़िलहिज्जा (यौमुत्तरविया): हज की नियत से एहराम बाँधें (तमत्तो वाले मक्का की रहाइश से), तल्बिया पढ़ें और मिना जाएँ। ज़ुहर, अस्र, मग़रिब, इशा और अगली फ़ज्र मिना में पढ़ें।',
'9 ज़िलहिज्जा (अरफ़ा का दिन): सूरज निकलने के बाद अरफ़ात जाएँ। ज़वाल के बाद से सूरज डूबने तक अरफ़ात में ठहरना (वुक़ूफ़) हज का सबसे अहम रुक्न है। दुआ, ज़िक्र और तल्बिया में वक़्त गुज़ारें।',
'10 की रात: सूरज डूबने के बाद मुज़दलिफ़ा जाएँ (मग़रिब अरफ़ात में न पढ़ें)। मग़रिब और इशा साथ पढ़ें, आराम करें, छोटी कंकरियाँ चुनें और फ़ज्र वहीं पढ़ें।',
'10 ज़िलहिज्जा (ईद): मिना जाकर सिर्फ़ बड़े जमरा (जमरतुल अक़बा) को 7 कंकरियाँ मारें; तल्बिया यहीं बंद। फिर क़ुर्बानी (तमत्तो/क़िरान वालों पर), फिर हल्क़ (सर मुँडाना) या तक़सीर (बाल कटवाना)। एहराम की ज़्यादातर पाबंदियाँ ख़त्म।',
'तवाफ़-ए-इफ़ाज़ा (रुक्न) और हज की सई: 10 तारीख़ या अगले दिनों में (अपने आलिम के मुताबिक़), फिर मिना वापस।',
'11 और 12 ज़िलहिज्जा: मिना में रहें। ज़वाल के बाद तीनों जमरात को तरतीब से — छोटा, बीच वाला, बड़ा — 7-7 कंकरियाँ मारें।',
'13 ज़िलहिज्जा: जो रुकें वे ज़वाल के बाद फिर तीनों जमरात को मारें। 12 को जाने वाले सूरज डूबने से पहले मिना छोड़ दें।',
'घर लौटने से पहले: तवाफ़-ए-विदा (रुख़सती तवाफ़)।']],
['Umrah — step by step','उमरा — क़दम-ब-क़दम',
['1. Ihram & niyyah at the miqat: ghusl/wudu, men wear two white sheets, women normal modest dress; make niyyah of Umrah before crossing the miqat (for flights, often announced on the plane).',
'2. Talbiya: "Labbaik Allahumma labbaik…" — men aloud, women softly — until you begin Tawaf.',
'3. Tawaf: 7 rounds around the Kaaba, starting and ending at the Hajar al-Aswad corner, Kaaba on your left.',
'4. Two rakat of Tawaf behind Maqam Ibrahim if possible, otherwise anywhere in the Masjid.',
'5. Drink Zamzam and make dua.',
'6. Sa\'i: 7 trips between Safa and Marwa, starting at Safa and ending at Marwa (Safa→Marwa counts as one).',
'7. Halq or taqsir: men shave or trim, women cut about a fingertip length. Your Umrah is complete.'],
['1. मीक़ात पर एहराम और नियत: ग़ुस्ल/वुज़ू, मर्द दो सफ़ेद चादरें, औरतें आम पर्दे वाला लिबास; मीक़ात से पहले उमरा की नियत करें (फ़्लाइट में अक्सर एलान होता है)।',
'2. तल्बिया: "लब्बैक अल्लाहुम्म लब्बैक…" — मर्द ऊँची आवाज़ में, औरतें आहिस्ता — तवाफ़ शुरू होने तक।',
'3. तवाफ़: काबा के गिर्द 7 चक्कर, हजर-ए-असवद वाले कोने से शुरू और वहीं ख़त्म, काबा बाईं तरफ़।',
'4. मुमकिन हो तो मक़ाम-ए-इब्राहीम के पीछे तवाफ़ की 2 रकात, वरना मस्जिद में कहीं भी।',
'5. ज़मज़म पिएँ और दुआ करें।',
'6. सई: सफ़ा और मरवा के बीच 7 चक्कर, सफ़ा से शुरू, मरवा पर ख़त्म (सफ़ा→मरवा एक चक्कर)।',
'7. हल्क़ या तक़सीर: मर्द सर मुँडाएँ या बाल कटवाएँ, औरतें उँगली के पोर बराबर बाल काटें। उमरा मुकम्मल।']],
['Madinah ziyarat — suggested route','मदीना ज़ियारत — सुझाया रास्ता',
['Masjid an-Nabawi: pray in the Masjid; Rawdah visit needs a slot booked in the Nusuk app; then give Salam at the grave of the Prophet ﷺ, then to Abu Bakr and Umar (RA). Be calm and respectful.',
'Jannat al-Baqi: right next to Masjid an-Nabawi; visit and make dua for those buried there (usually open for men after Fajr/Asr — check on site).',
'Masjid Quba: the first mosque in Islam, a few km south of Masjid an-Nabawi; praying two rakat there carries great reward (hadith). Many go on Saturday morning.',
'Masjid al-Qiblatain: where the Qibla changed from Jerusalem to the Kaaba.',
'Seven Mosques (Khandaq area): site of the Battle of the Trench, near Mount Sal\'.',
'Uhud & Shuhada: Mount Uhud and the graves of the martyrs of Uhud, including Sayyiduna Hamza (RA); Mount Rumah (Archers\' hill) is nearby.',
'Suggested order for a ziyarat tour: Quba → Qiblatain → Seven Mosques → Uhud (or join an organised ziyarat bus/taxi). Masjid an-Nabawi and Baqi are on foot.',
'Tips: carry water, ID and Nusuk app; agree the taxi fare before starting; return in time for prayers; distances/timings vary — ask locally.'],
['मस्जिद-ए-नबवी: मस्जिद में नमाज़ पढ़ें; रौज़ा के लिए Nusuk ऐप में स्लॉट बुक करना ज़रूरी; फिर नबी ﷺ के रौज़ा-ए-मुबारक पर सलाम, फिर अबू बक्र और उमर (रज़ि.) पर। सुकून और अदब से।',
'जन्नतुल बक़ी: मस्जिद-ए-नबवी के बिल्कुल पास; ज़ियारत करें और दफ़्न लोगों के लिए दुआ करें (आम तौर पर मर्दों के लिए फ़ज्र/अस्र के बाद खुलता है — मौक़े पर देखें)।',
'मस्जिद-ए-क़ुबा: इस्लाम की पहली मस्जिद, मस्जिद-ए-नबवी से कुछ किलोमीटर दक्षिण; वहाँ 2 रकात का बड़ा सवाब (हदीस)। बहुत लोग सनीचर की सुबह जाते हैं।',
'मस्जिद-ए-क़िबलतैन: जहाँ क़िबला बैतुल मक़दिस से काबा की तरफ़ बदला।',
'सात मस्जिदें (ख़ंदक़ इलाक़ा): ग़ज़वा-ए-ख़ंदक़ की जगह, जबल-ए-सल्अ के पास।',
'उहुद और शुहदा: उहुद पहाड़ और शुहदा-ए-उहुद की क़ब्रें, जिनमें सय्यिदना हमज़ा (रज़ि.) भी; पास में जबल-ए-रुमात (तीरंदाज़ों की पहाड़ी)।',
'ज़ियारत का सुझाया क्रम: क़ुबा → क़िबलतैन → सात मस्जिदें → उहुद (या ज़ियारत बस/टैक्सी लें)। मस्जिद-ए-नबवी और बक़ी पैदल।',
'टिप्स: पानी, आईडी और Nusuk ऐप साथ रखें; टैक्सी का किराया पहले तय करें; नमाज़ के वक़्त तक लौटें; दूरी/वक़्त अलग-अलग — मौक़े पर पूछें।']]];
const HARAM_SVG=()=>`<svg viewBox="0 0 360 400" width="100%" role="img" aria-label="Masjid al-Haram simple diagram" style="background:#fff;border-radius:14px;border:1px solid #e6e1d6;font-family:sans-serif">
<rect x="20" y="20" width="230" height="360" rx="10" fill="#f6f0e4" stroke="#b8954f" stroke-width="2"/>
<circle cx="135" cy="200" r="70" fill="#fffaf0" stroke="#c9a45c" stroke-dasharray="4 4"/><text x="135" y="122" font-size="9" text-anchor="middle" fill="#5f6b4e">${t('Mataf (Tawaf area)','मताफ़ (तवाफ़)')}</text>
<rect x="120" y="185" width="30" height="30" fill="#111"/><rect x="120" y="190" width="30" height="3" fill="#c9a45c"/><text x="135" y="232" font-size="10" text-anchor="middle" font-weight="bold">${t('Kaaba','काबा')}</text>
<circle cx="150" cy="215" r="4" fill="#c0392b"/><text x="170" y="250" font-size="9" fill="#c0392b">${t('Hajar al-Aswad corner','हजर-ए-असवद कोना')}</text><line x1="152" y1="217" x2="170" y2="243" stroke="#c0392b"/>
<path d="M118 180 A22 22 0 0 1 152 180" fill="none" stroke="#1f4d3a" stroke-width="3"/><text x="135" y="165" font-size="9" text-anchor="middle" fill="#1f4d3a">${t('Hijr Ismail','हिज्र-ए-इस्माईल')}</text>
<rect x="160" y="168" width="8" height="8" fill="#b8954f"/><text x="172" y="176" font-size="9">${t('Maqam Ibrahim','मक़ाम-ए-इब्राहीम')}</text>
<rect x="275" y="40" width="50" height="320" rx="8" fill="#e8f0ea" stroke="#1f4d3a"/><text x="300" y="205" font-size="10" text-anchor="middle" transform="rotate(-90 300 205)" fill="#1f4d3a">${t("Mas'a (Sa'i)","मसआ (सई)")}</text>
<circle cx="300" cy="345" r="9" fill="#1f4d3a"/><text x="300" y="392" font-size="10" text-anchor="middle" font-weight="bold">${t('Safa','सफ़ा')}</text>
<circle cx="300" cy="55" r="9" fill="#1f4d3a"/><text x="300" y="34" font-size="10" text-anchor="middle" font-weight="bold">${t('Marwah','मरवा')}</text>
<g font-size="9" fill="#7a5c1e"><rect x="125" y="375" width="20" height="8" fill="#b8954f"/><text x="135" y="396" text-anchor="middle">${t('King Abdulaziz Gate','किंग अब्दुलअज़ीज़ गेट')}</text>
<rect x="12" y="190" width="8" height="20" fill="#b8954f"/><text x="24" y="290" transform="rotate(-90 24 290)">${t('King Fahd Gate','किंग फ़हद गेट')}</text>
<rect x="60" y="12" width="20" height="8" fill="#b8954f"/><text x="70" y="12" text-anchor="middle" dy="-2">${t('Umrah Gate','उमरा गेट')}</text>
<rect x="250" y="70" width="8" height="20" fill="#b8954f"/><text x="246" y="66" text-anchor="end">${t('Bab as-Salam','बाब-उस-सलाम')}</text></g>
</svg><p class="sub" style="text-align:center">⚠️ ${t('Simple diagram, not to scale. Positions are approximate — follow on-site signs.','आसान ख़ाका, पैमाने पर नहीं। जगहें अंदाज़न — मौक़े के बोर्ड देखें।')}</p>`;
V.guides=()=>`<h1>${t('Guides','गाइड')}</h1><p class="sub">${t('Hajj, Umrah, Haram map and Madinah ziyarat.','हज, उमरा, हरम का नक़्शा और मदीना ज़ियारत।')}</p>`+GUIDE_NOTE()+[0,1].map(i=>gd(i,i===0)).join('')+`<details id="haram-map"><summary>3. ${t('Masjid al-Haram map','मस्जिद-ए-हराम नक़्शा')}</summary>${HARAM_SVG()}${spk(t('Masjid al-Haram simple diagram. Kaaba in the centre with the Mataf around it. Hajar al-Aswad corner, Maqam Ibrahim and Hijr Ismail near the Kaaba. Safa and Marwah are connected by the Masa on the eastern side. Major gates include King Abdulaziz Gate, King Fahd Gate, Umrah Gate and Bab as-Salam. Not to scale.','मस्जिद-ए-हराम का आसान ख़ाका। बीच में काबा और उसके गिर्द मताफ़। काबा के पास हजर-ए-असवद का कोना, मक़ाम-ए-इब्राहीम और हिज्र-ए-इस्माईल। सफ़ा और मरवा मसआ से जुड़े हैं। बड़े दरवाज़ों में किंग अब्दुलअज़ीज़ गेट, किंग फ़हद गेट, उमरा गेट और बाब-उस-सलाम। पैमाने पर नहीं।'))}</details>`+gd(2,false,4);
function gd(i,open,n){const g=GTOP[i],b=L==='hi'?g[3]:g[2];return `<details${open?' open':''}><summary>${n||i+1}. ${t(g[0],g[1])}</summary><ul>${b.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${spk(t(g[0],g[1])+'. '+b.join(' '))}</details>`}
// Ask Zoya — demo Q&A (keyword matching, reuses home Zoya sample answers + Rules/Guides content). Not live AI.
const ZQA=[
['इहराम,एहराम,ihram,मना,कपड़े,forbidden','What is forbidden in ihram?','इहराम में क्या मना है?','For men, stitched clothes; for everyone, perfume, cutting hair or nails, hunting and nikah are forbidden. Also avoid indecent talk, sin and arguments — Quran: al-Baqarah 2:197. Hunting: al-Ma\'idah 5:95.','इहराम में मर्दों के लिए सिले हुए कपड़े, और सबके लिए ख़ुशबू लगाना, बाल या नाख़ून काटना, शिकार और निकाह मना हैं। साथ ही बेहूदा बात, गुनाह और झगड़े से बचना है — क़ुरआन: अल-बक़रह 2:197। शिकार की मनाही: अल-माइदह 5:95।'],
['तवाफ़,तवाफ,tawaf,चक्कर,rounds','How many rounds in Tawaf?','तवाफ़ में कितने चक्कर होते हैं?','Tawaf is 7 rounds around the Kaaba, starting from the Hajar al-Aswad corner, Kaaba on your left. Between Rukn al-Yamani and Hajar al-Aswad it is sunnah to recite "Rabbana atina fid-dunya hasanah…" — Quran 2:201.','तवाफ़ में काबा के गिर्द सात चक्कर लगाए जाते हैं, हजर-ए-असवद से शुरू करके। रुक्न-ए-यमानी और हजर-ए-असवद के बीच \'रब्बना आतिना फ़िद्दुनिया हसनह…\' पढ़ना मसनून है — क़ुरआन: अल-बक़रह 2:201।'],
['अरफ़ा,अरफा,अरफ़ात,अरफात,arafa,arafat,वुक़ूफ़,वुकूफ','Why is the Day of Arafah important?','अरफ़ा का दिन क्यों अहम है?','Staying at Arafat (wuquf) on 9 Dhul Hijjah is the most important pillar of Hajj. Famous hadith: "Hajj is Arafah" — Tirmidhi, Nasa\'i. Returning from Arafat: Quran 2:198–199.','अरफ़ात में ठहरना (वुक़ूफ़) हज का सबसे अहम रुक्न है। मशहूर हदीस है: \'हज अरफ़ा है\' — सुनन तिर्मिज़ी, सुनन नसाई। अरफ़ात से लौटने का ज़िक्र: अल-बक़रह 2:198–199।'],
['सई,सफ़ा,सफा,मरवा,sai,safa,marwa,हाजरा','Why Sa\'i between Safa and Marwah?','सफ़ा-मरवा की सई क्यों?','Safa and Marwah are among the signs of Allah — Quran 2:158. Sa\'i (7 trips, starting at Safa, ending at Marwah) remembers Hazrat Hajar\'s search for water, narrated in Sahih Bukhari.','सफ़ा और मरवा अल्लाह की निशानियों में से हैं — क़ुरआन: अल-बक़रह 2:158। सई (7 चक्कर, सफ़ा से शुरू, मरवा पर ख़त्म) हज़रत हाजरा (रज़ि.) की पानी की तलाश की याद है, जिसका वाक़िया सहीह बुख़ारी में है।'],
['उमरा,umrah,तरीक़ा,steps','How do I perform Umrah?','उमरा कैसे करें?','1) Ihram and niyyah before the miqat 2) Talbiya 3) Tawaf, 7 rounds 4) 2 rakat, behind Maqam Ibrahim if possible 5) Zamzam 6) Sa\'i, 7 trips Safa→Marwah 7) Halq or taqsir. See Explore → Guides.','1) मीक़ात से पहले एहराम और नियत 2) तल्बिया 3) तवाफ़, 7 चक्कर 4) 2 रकात, हो सके तो मक़ाम-ए-इब्राहीम के पीछे 5) ज़मज़म 6) सई, 7 चक्कर सफ़ा→मरवा 7) हल्क़ या तक़सीर। देखें: एक्सप्लोर → गाइड।'],
['रमी,जमरात,जमरा,कंकरी,rami,jamarat,pebble','How is Rami (stoning) done?','रमी (जमरात) कैसे करें?','On 10 Dhul Hijjah only the big Jamarah (al-Aqabah), 7 pebbles. On 11 and 12 (and 13 if staying), after Zawal, all three in order — small, middle, big — 7 pebbles each.','10 ज़िलहिज्जा को सिर्फ़ बड़ा जमरा (अक़बा), 7 कंकरियाँ। 11 और 12 (और रुकें तो 13) को ज़वाल के बाद तीनों तरतीब से — छोटा, बीच वाला, बड़ा — 7-7 कंकरियाँ।'],
['मुज़दलिफ़ा,मुजदलिफा,muzdalifah','What happens at Muzdalifah?','मुज़दलिफ़ा में क्या करते हैं?','After sunset on the 9th go from Arafat to Muzdalifah, pray Maghrib and Isha together, rest, collect pebbles and pray Fajr there.','9 तारीख़ को सूरज डूबने के बाद अरफ़ात से मुज़दलिफ़ा जाएँ, मग़रिब और इशा साथ पढ़ें, आराम करें, कंकरियाँ चुनें और फ़ज्र वहीं पढ़ें।'],
['क़ुर्बानी,कुर्बानी,qurbani,हल्क़,हल्क,बाल,taqsir','Qurbani and halq — in what order?','क़ुर्बानी और हल्क़ की तरतीब?','On 10 Dhul Hijjah: Rami of the big Jamarah, then qurbani (for Tamattu/Qiran), then halq or taqsir. Book qurbani only through official coupons/banks. Follow your scholar on the sequence.','10 ज़िलहिज्जा: बड़े जमरा की रमी, फिर क़ुर्बानी (तमत्तो/क़िरान वालों पर), फिर हल्क़ या तक़सीर। क़ुर्बानी सिर्फ़ आधिकारिक कूपन/बैंक से। तरतीब में अपने आलिम की बात मानें।'],
['रौज़ा,रोज़ा,rawdah,मदीना,madinah,nusuk,ज़ियारत','How to visit Rawdah in Madinah?','मदीना में रौज़ा की ज़ियारत कैसे?','A Rawdah visit needs a slot booked in the Nusuk app. Then give Salam at the grave of the Prophet ﷺ, then to Abu Bakr and Umar (RA). Also visit Baqi, Quba, Qiblatain, Uhud — see Guides.','रौज़ा के लिए Nusuk ऐप में स्लॉट बुक करना ज़रूरी है। फिर नबी ﷺ के रौज़ा-ए-मुबारक पर सलाम, फिर अबू बक्र और उमर (रज़ि.) पर। बक़ी, क़ुबा, क़िबलतैन, उहुद भी — गाइड देखें।'],
['विदा,wida,farewell,वापसी','What is Tawaf al-Wida?','तवाफ़-ए-विदा क्या है?','The farewell tawaf done before leaving Makkah for home.','मक्का से घर लौटने से पहले किया जाने वाला रुख़सती तवाफ़।'],
['औरत,ख़्वातीन,women,माहवारी,हैज़,menses','Rules for women in ihram?','औरतों के लिए एहराम के मसाइल?','Wear normal modest clothing; no niqab or gloves in ihram. During menses all rites except Tawaf can be done — ask a scholar for details.','आम पर्दे वाला लिबास; एहराम में चेहरे पर नक़ाब और दस्ताने नहीं। माहवारी में तवाफ़ के अलावा बाक़ी अरकान अदा कर सकती हैं — मसाइल आलिमा/आलिम से पूछें।'],
['खोया,गुम,lost,रास्ता,भटक','I am lost / separated from my group','मैं रास्ता भटक गया / ग्रुप से बिछड़ गया','Stay calm, stay where you are, show your ID card/wristband to officials or Indian Hajj volunteers, and call your group leader. You can also use Lost & Found in this app.','घबराएँ नहीं, एक जगह रुकें, अपना आईडी कार्ड/रिस्टबैंड अधिकारियों या भारतीय हज वॉलंटियर को दिखाएँ और अपने ग्रुप लीडर को फ़ोन करें। ऐप में खोया-पाया भी देखें।']];
let ZL=null;const ZN=x=>x.toLowerCase().replace(/[\u093c]/g,'');
function zFind(x){const n=ZN(x);let b=null,s=0;ZQA.forEach(q=>{const c=q[0].split(',').filter(k=>n.includes(ZN(k))).length;if(c>s){s=c;b=q}});return b}
function zReply(q){const box=document.getElementById('zbox');if(!box||!q.trim())return;const m=zFind(q);const a=m?t(m[3],m[4]):t('This is a demo — I could not find this. For fiqh questions please consult your ulama, or contact the Hajj helpline / your Khadimul Hujjaj. Try a suggested question below.','यह डेमो है — इसका जवाब मेरे पास नहीं मिला। फ़िक़्ही मसाइल के लिए अपने उलमा से पूछें, या हज हेल्पलाइन / अपने ख़ादिमुल हुज्जाज से संपर्क करें। नीचे दिए सवालों में से कोई चुनें।');
box.insertAdjacentHTML('beforeend',`<div class="zm u">${esc(q)}</div><div class="zm z">${esc(a)}</div>`);box.lastElementChild.insertAdjacentHTML('beforeend',' '+spk(a));box.scrollTop=box.scrollHeight;
if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(a);u.lang=L==='hi'?'hi-IN':'en-IN';u.rate=.92;speechSynthesis.speak(u)}}
window.zAskQ=e=>{e.preventDefault();const i=document.getElementById('zqq');zReply(i.value);i.value='';return false};
window.zChip=i=>zReply(t(ZQA[i][1],ZQA[i][2]));
const zErr=c=>c==='not-allowed'||c==='service-not-allowed'?'माइक की इजाज़त दें (ब्राउज़र सेटिंग में Microphone → Allow) / Please allow microphone access':c==='no-speech'?'आवाज़ नहीं सुनाई दी, फिर से बोलें / Didn\'t hear anything, try again':c==='network'?'इंटरनेट चेक करें / Check internet':'लिखकर पूछें / Please type your question';window.zMic=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return alert(t('Mic not supported on this browser — please type.','इस ब्राउज़र में माइक सपोर्ट नहीं — लिखकर पूछें।'));const r=new SR();r.lang=L==='hi'?'hi-IN':'en-IN';r.interimResults=true;const b=document.getElementById('zmicb'),q=document.getElementById('zqq'),ph=q.placeholder;let it='',done=false;const go=s=>{if(done||!(s=s.trim()))return;done=true;q.value='';zReply(s)};b.textContent='⏺';r.onresult=e=>{let f='',i='';for(let k=e.resultIndex||0;k<e.results.length;k++){const x=e.results[k];x.isFinal?f+=x[0].transcript:i+=x[0].transcript}if(f){it='';go(f)}else{it=i;q.value=i}};r.onerror=e=>{done=true;q.value='';q.placeholder=zErr(e&&e.error);setTimeout(()=>q.placeholder=ph,5000)};r.onend=()=>{go(it);b.textContent='🎤'};try{r.start()}catch(_){b.textContent='🎤'}};
V.zoya=()=>`<style>.zh{display:flex;gap:12px;align-items:center}.zh img{width:64px;height:64px;border-radius:50%;object-fit:cover;border:2px solid #c9a45c}#zbox{max-height:360px;overflow:auto;display:flex;flex-direction:column;gap:8px;margin:10px 0}.zm{padding:9px 12px;border-radius:14px;max-width:88%;line-height:1.5}.zm.u{align-self:flex-end;background:#1f4d3a;color:#fff}.zm.z{align-self:flex-start;background:#fffaf0;border:1px solid #c9a45c77}.zf{display:flex;gap:6px}.zf input{flex:1;margin:0}.zc{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.zc button{border:1px solid #c9a45c;background:transparent;color:#1f4d3a;border-radius:999px;padding:6px 10px;font-size:13px}</style>
<div class="zh"><img src="assets/zoya.jpg" alt="Zoya"><div><h1 style="margin:0">${t('Ask Zoya','ज़ोया से पूछें')}</h1><p class="sub" style="margin:2px 0">${t('Ask anything about Hajj & Umrah','हज और उमरा के बारे में कुछ भी पूछें')}</p></div></div>
<span class="tag s">${t('Demo — sample answers, not live AI','डेमो — नमूना जवाब, लाइव AI नहीं')}</span>
<div class="card"><div id="zbox"><div class="zm z">${t('Assalamu alaikum! I am Zoya. Ask your question.','अस्सलामु अलैकुम! मैं ज़ोया हूँ। अपना सवाल पूछें।')}</div></div>
<form class="zf" onsubmit="return zAskQ(event)"><input id="zqq" placeholder="${t('Type your question…','अपना सवाल लिखें…')}" autocomplete="off"><button type="button" id="zmicb" class="btn o" onclick="zMic()" aria-label="mic">🎤</button><button class="btn">${t('Ask','पूछें')}</button></form>
<div class="zc">${ZQA.map((q,i)=>`<button type="button" onclick="zChip(${i})">${esc(t(q[1],q[2]))}</button>`).join('')}</div></div>
<div class="note">${t('For fiqh details please confirm with your ulama.','फ़िक़्ही मसाइल अपने उलमा से कन्फ़र्म करें।')}</div>`;
