V.mashaer=()=>`<h1>${t('Mashaer Map','मशाइर नक़्शा')}</h1><span class="tag s">${t('Schematic, not to scale','ख़ाका, पैमाने पर नहीं')}</span><div class="card"><svg viewBox="0 0 360 220" width="100%" role="img" aria-label="Mashaer schematic"><g font-size="13" font-family="Mukta"><circle cx="40" cy="110" r="22" fill="#1f4d3a"/><text x="40" y="150" text-anchor="middle">${t('Makkah','मक्का')}</text><circle cx="140" cy="60" r="20" fill="#b8954f"/><text x="140" y="35" text-anchor="middle">${t('Mina (8th)','मिना (8)')}</text><circle cx="310" cy="110" r="24" fill="#b8954f"/><text x="310" y="150" text-anchor="middle">${t('Arafat (9th)','अरफ़ात (9)')}</text><circle cx="210" cy="170" r="20" fill="#b8954f"/><text x="210" y="205" text-anchor="middle">${t('Muzdalifah','मुज़दलिफ़ा')}</text><path d="M62 104L120 66M160 64L288 102M290 126L230 166M190 162L150 80" stroke="#5f6b4e" stroke-width="2" fill="none" stroke-dasharray="5 4"/></g></svg>
<ol>${(L==='hi'?['8 ज़िलहिज्जा: मक्का → मिना','9: मिना → अरफ़ात (वुक़ूफ़)','9 रात: अरफ़ात → मुज़दलिफ़ा','10: मुज़दलिफ़ा → मिना (रमी, क़ुर्बानी, हल्क़) → मक्का (तवाफ़-ए-इफ़ाज़ा)','11–13: मिना में रमी']:['8 Dhul Hijjah: Makkah → Mina','9th: Mina → Arafat (Wuquf)','9th night: Arafat → Muzdalifah','10th: Muzdalifah → Mina (Rami, Qurbani, Halq) → Makkah (Tawaf al-Ifadah)','11–13: Rami in Mina']).map(x=>`<li>${x}</li>`).join('')}</ol></div>`;
V.qurbani=()=>info(t('Qurbani','क़ुर्बानी'),L==='hi'?['हज-ए-तमत्तो और क़िरान में क़ुर्बानी वाजिब है।','अधिकृत (सरकारी) कूपन / बैंक से ही बुक करें।','क़ुर्बानी के बाद ही हल्क़ — अपने आलिम की तरतीब मानें।']:['Qurbani is required for Hajj Tamattu and Qiran.','Book only through authorised (official) coupons/banks.','Follow your scholar\'s guidance on the sequence with Halq.'],['https://adahi.org/','Adahi (official Saudi project)']);
V.women=()=>info(t('Women Pilgrims','ख़्वातीन हाजी'),L==='hi'?['एहराम में आम पर्दे वाला लिबास; चेहरे पर नक़ाब और दस्ताने न पहनें।','माहवारी में तवाफ़ के अलावा बाक़ी अरकान अदा कर सकती हैं — मसाइल के लिए आलिमा/आलिम से पूछें।','औरतों के लिए हरम और रौज़ा में अलग वक़्त/दरवाज़े।','सेहत के लिए ज़रूरी चीज़ें साथ रखें।']:['In Ihram wear normal modest clothing; do not wear niqab or gloves.','During menses all rites except Tawaf can be done — ask a scholar for details.','Separate timings/gates for women at the Haram and Rawdah.','Carry personal health essentials.']);
V.food=()=>info(t('Food Guide','खाना गाइड'),L==='hi'?['बिल्डिंग/कैंप में मिलने वाला खाना वक़्त पर लें।','बाहर ताज़ा और गर्म खाना ही खाएँ; कटे फल से बचें।','ज़मज़म और पानी ख़ूब पिएँ।','शुगर/बीपी वाले अपनी डाइट का ख़्याल रखें।']:['Take meals provided at your building/camp on time.','Outside, eat freshly cooked hot food; avoid pre-cut fruit.','Drink plenty of Zamzam and water.','Diabetics/BP patients should follow their diet.']);
