// LinkedIn: PLACEHOLDER URL — link jald aayega (real URL not yet provided by Saiful; replace LI_URL)
const LI_URL='https://www.linkedin.com/company/hajcare-ai';

// Demo-only: Social Media Video 1 local attach (browser IndexedDB; not uploaded to server)
const HC_V1_DB='hajcare-demo-social-v1', HC_V1_STORE='videos', HC_V1_KEY='slot1';
let HC_V1_URL=null;
const hcV1Open=()=>new Promise((res,rej)=>{if(!window.indexedDB)return rej(new Error('no-idb'));const r=indexedDB.open(HC_V1_DB,1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(HC_V1_STORE))db.createObjectStore(HC_V1_STORE)};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const hcV1Get=async()=>{try{const db=await hcV1Open();return await new Promise((res,rej)=>{const q=db.transaction(HC_V1_STORE,'readonly').objectStore(HC_V1_STORE).get(HC_V1_KEY);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}catch(_){return null}};
const hcV1Put=async(rec)=>{const db=await hcV1Open();return new Promise((res,rej)=>{const q=db.transaction(HC_V1_STORE,'readwrite').objectStore(HC_V1_STORE).put(rec,HC_V1_KEY);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})};
const hcV1Del=async()=>{try{const db=await hcV1Open();await new Promise((res,rej)=>{const q=db.transaction(HC_V1_STORE,'readwrite').objectStore(HC_V1_STORE).delete(HC_V1_KEY);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}catch(_){}};
const hcV1Revoke=()=>{if(HC_V1_URL){try{URL.revokeObjectURL(HC_V1_URL)}catch(_){} HC_V1_URL=null}};
const hcV1Status=(el,msg,ok)=>{if(!el)return;el.textContent=msg;el.className=ok?'ok':'note'};
const hcV1Show=(blob,meta)=>{const v=$('#hc-v1-player'),metaEl=$('#hc-v1-meta'),st=$('#hc-v1-status'),clr=$('#hc-v1-clear');if(!v)return;hcV1Revoke();HC_V1_URL=URL.createObjectURL(blob);v.src=HC_V1_URL;v.style.display='block';if(metaEl)metaEl.textContent=`${meta.name||'video'} · ${Math.round((meta.size||blob.size||0)/1048576*10)/10} MB`;if(clr)clr.style.display='inline-flex';hcV1Status(st,t('Attached on this browser only — not uploaded to any server.','सिर्फ़ इस ब्राउज़र में सेव — किसी सर्वर पर अपलोड नहीं।'),true)};
const hcV1ClearUI=()=>{const v=$('#hc-v1-player'),metaEl=$('#hc-v1-meta'),st=$('#hc-v1-status'),clr=$('#hc-v1-clear'),inp=$('#hc-v1-file');hcV1Revoke();if(v){v.removeAttribute('src');v.load();v.style.display='none'}if(metaEl)metaEl.textContent='';if(clr)clr.style.display='none';if(inp)inp.value='';hcV1Status(st,t('No file attached yet. Choose a video for Video 1.','अभी कोई फ़ाइल नहीं। Video 1 के लिए वीडियो चुनें।'),false)};
async function hcV1Bind(){const inp=$('#hc-v1-file'),btn=$('#hc-v1-attach'),clr=$('#hc-v1-clear'),st=$('#hc-v1-status');if(!inp||!btn)return;btn.onclick=()=>inp.click();clr&&(clr.onclick=async()=>{await hcV1Del();hcV1ClearUI();hcV1Status(st,t('Cleared from this browser.','इस ब्राउज़र से हटा दिया।'),false)});inp.onchange=async()=>{const f=inp.files&&inp.files[0];if(!f)return;if(!/^video\//.test(f.type)&&!/\.(mp4|webm|mov|m4v|mkv)$/i.test(f.name||'')){hcV1Status(st,t('Please choose a video file.','कृपया वीडियो फ़ाइल चुनें।'),false);inp.value='';return}try{await hcV1Put({blob:f,name:f.name,type:f.type||'video/mp4',size:f.size,updatedAt:Date.now()});hcV1Show(f,{name:f.name,size:f.size})}catch(e){hcV1Status(st,t('Could not save on this device (storage full or blocked). Preview may still work until you leave the page.','इस डिवाइस पर सेव नहीं हो सका। पेज छोड़ने तक प्रीव्यू चल सकता है।'),false);hcV1Show(f,{name:f.name,size:f.size})}};const existing=await hcV1Get();if(existing&&existing.blob)hcV1Show(existing.blob,{name:existing.name,size:existing.size});else hcV1ClearUI()}

V.social=()=>`<h1>${t('Social Media','सोशल मीडिया')}</h1><p class="sub">${t('Links as listed on hajjcare.in','hajjcare.in पर दिए गए लिंक')}</p><div class="grid">${[[BRAND.wa,'WhatsApp','https://whatsapp.com/channel/LdH4cHBImrWIAwX2wv83Xz'],[BRAND.ig,'Instagram','https://www.instagram.com/rafiqulharmain'],[BRAND.fb,'Facebook','https://www.facebook.com/share/p/1BpoqCgvsq/'],[BRAND.yt,'YouTube','https://youtube.com/@rafiqulharmain-y8d'],[BRAND.x,'X','https://x.com/UlHaramain50604'],[BRAND.li,t('LinkedIn','लिंक्डइन'),LI_URL,'li']].map(s=>`<a class="tile brand${s[3]?' '+s[3]:''}" target="_blank" rel="noopener" href="${s[2]}"><i>${s[0]}</i><b>${s[1]}</b></a>`).join('')}</div><h2>${t('100 Videos','100 वीडियो')}</h2><div class="note">${t('A 100-video series (one per training day) will be listed here in the live app. Placeholder.','100 वीडियो की सीरीज़ (हर ट्रेनिंग दिन का एक) लाइव ऐप में यहाँ होगी। प्लेसहोल्डर।')}</div><div class="note">${t('Video 1 attach is demo-only on this device (IndexedDB). It is not uploaded to HajCare servers.','Video 1 का अटैच सिर्फ़ इस डिवाइस के डेमो के लिए है (IndexedDB)। HajCare सर्वर पर अपलोड नहीं होता।')}</div><div class="grid"><div class="tile" id="hc-v1-tile" data-slot="1" style="grid-column:1/-1;align-items:stretch;text-align:left"><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><i>${ICO.video}</i><b>${t('Video','वीडियो')} 1</b><button type="button" class="btn" id="hc-v1-attach">${t('Attach / Choose file','अटैच / फ़ाइल चुनें')}</button><button type="button" class="btn o" id="hc-v1-clear" style="display:none">${t('Clear','हटाएँ')}</button><input id="hc-v1-file" type="file" accept="video/*,.mp4,.webm,.mov,.m4v" data-slot="1" hidden></div><video id="hc-v1-player" controls playsinline style="display:none;width:100%;max-height:360px;margin-top:10px;border-radius:12px;background:#000"></video><div id="hc-v1-meta" style="font-size:12px;margin-top:6px;color:#5f6b4e"></div><div id="hc-v1-status" class="note" style="margin-top:8px">${t('No file attached yet. Choose a video for Video 1.','अभी कोई फ़ाइल नहीं। Video 1 के लिए वीडियो चुनें।')}</div></div>${Array.from({length:5},(_,i)=>`<div class="tile" data-slot="${i+2}"><i>${ICO.video}</i><b>${t('Video','वीडियो')} ${i+2}</b><span>${t('Coming soon','जल्द')}</span></div>`).join('')}</div>`;
const form=(key,title,intro,fields,okMsg)=>`<h1>${title}</h1><p class="sub">${intro}</p><span class="tag s">${t('Demo — saved only on this phone, nothing is sent','डेमो — सिर्फ़ इस फ़ोन में सेव, कहीं भेजा नहीं जाता')}</span><form class="card" data-store="${key}" data-ok="${esc(okMsg)}">${fields.map(f=>f[1]==='select'?`<label>${f[2]}</label><select name="${f[0]}">${f[3].map(o=>`<option>${o}</option>`).join('')}</select>`:f[1]==='area'?`<label>${f[2]}</label><textarea name="${f[0]}" rows="3" required></textarea>`:`<label>${f[2]}</label><input name="${f[0]}" type="${f[1]}" ${f[3]===0?'':'required'}>`).join('')}<div class="cta"><button class="btn">${t('Submit','जमा करें')}</button></div><div class="res"></div></form><div id="list"></div>`;
V.lost=()=>`<h1>${t('Lost & Found','खोया-पाया')}</h1><span class="tag s">${t('Demo — stored on this device only','डेमो — सिर्फ़ इस डिवाइस में')}</span><form class="card" data-store="hc-lost" data-ok="${t('Report saved','रिपोर्ट सेव हुई')}"><label>${t('Type','क़िस्म')}</label><select name="type"><option>${t('Lost','खोया')}</option><option>${t('Found','पाया')}</option></select><label>${t('Item / person','सामान / व्यक्ति')}</label><input name="item" required><label>${t('Place','जगह')}</label><input name="place" required><label>${t('Contact','संपर्क')}</label><input name="contact" type="tel"><div class="cta"><button class="btn">${t('Report','रिपोर्ट करें')}</button></div><div class="res"></div></form><label>🔎 ${t('Search reports','रिपोर्ट खोजें')}</label><input id="q"><div id="list"></div>`;
V.grievance=()=>form('hc-griev',t('Grievance','शिकायत'),t('Tell us your problem; in the live app it reaches the right team.','अपनी परेशानी बताएँ; लाइव ऐप में यह सही टीम तक पहुँचेगी।'),[['name','text',t('Name','नाम')],['cover','text',t('Cover number (optional)','कवर नंबर (वैकल्पिक)'),0],['cat','select',t('Category','विषय'),L==='hi'?['रहाइश','खाना','सफ़र','सेहत','अन्य']:['Accommodation','Food','Transport','Health','Other']],['msg','area',t('Details','तफ़सील')]],t('Grievance saved (demo).','शिकायत सेव हुई (डेमो)।'));
