V.after=()=>{let h=`<h1>${t('Hajj Mabroor — 40 Days','हज मबरूर — 40 दिन')}</h1><div class="card"><h3>${t('Welcome back!','वापसी मुबारक!')}</h3><p class="ar">${HAD[0]}</p><p class="hc-explore-meaning" data-original-en='"Whoever performs Hajj for Allah and avoids obscenity and wrongdoing returns (free of sin) like the day his mother bore him." — Bukhari & Muslim'>${HAD[1]}</p>${spk(HAD[1])}</div><span class="tag s">${t('Sample program','नमूना प्रोग्राम')}</span>`;for(let d=1;d<=40;d++){const m=MABROOR[(d-1)%10],w=Math.ceil(d/10);const R=t(`Reflect: how did "${m[0]}" show in your day? (week ${w})`,`ग़ौर करें: आज "${m[1]}" आपकी ज़िंदगी में कैसे दिखा? (हफ़्ता ${w})`),G=t('Gratitude: write 3 blessings of today.','शुक्र: आज की 3 नेमतें लिखें।'),D=t('Dua: O Allah, accept my Hajj and keep me steadfast. (Rabbana taqabbal minna)','दुआ: ऐ अल्लाह, मेरा हज क़ुबूल फ़रमा और मुझे साबित-क़दम रख। (रब्बना तक़ब्बल मिन्ना)');h+=`<details><summary>${t('Day','दिन')} ${d} — ${t(m[0],m[1])}</summary><ul><li>${R}</li><li>${G}</li><li>${D}</li></ul>${spk([t(m[0],m[1]),R,G,D].join('. '))}</details>`}return h};
