V.videos=()=>`<style>.vf{max-width:640px;margin:0 auto}.vc{padding:0;overflow:hidden}.vc .vh{display:flex;gap:10px;align-items:center;padding:12px 14px}.vc .av{width:40px;height:40px;border-radius:50%;background:#1f4d3a;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}.vc .vh small{display:block;color:#5f6b4e;font-size:12px}.vc .vp{position:relative;aspect-ratio:16/9;background:#000;cursor:pointer}.vc .vp img,.vc .vp iframe,.vc .vp .vx{position:absolute;inset:0;width:100%;height:100%;border:0;object-fit:cover}.vc .vp .pl{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:64px;height:64px;border-radius:50%;background:#1f4d3acc;color:#fff;font-size:28px;display:flex;align-items:center;justify-content:center;border:2px solid #c9a45c}.vc .vb{padding:10px 14px 14px}.vc .vb h3{margin:0 0 6px;font-size:16px}.vx{background:#1f4d3aee;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:10px;text-align:center}.vx button{border:1px solid #c9a45c;background:#fffaf0;color:#1f4d3a;border-radius:999px;padding:6px 12px;font-size:13px}.vt{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.vt button{border:1px solid #c9a45c;background:transparent;color:#1f4d3a;border-radius:999px;padding:6px 14px;font-size:14px}.vt button.on{background:#1f4d3a;color:#fff}</style><h1>${t('HajCare Videos','HajCare वीडियो')}</h1><p class="sub">${t('Only Hajj, Umrah, Quran and Hadith videos.','सिर्फ़ हज, उमराह, क़ुरआन और हदीस के वीडियो।')}</p><div class="vt" id="vtabs">${[['all','All','सब'],...VCATS].map(c=>`<button data-vc="${c[0]}" class="${c[0]===VCAT?'on':''}">${t(c[1],c[2])}</button>`).join('')}</div><div class="note">${t('Curated list. Videos play from YouTube; tap a video to load it.','चुनी हुई लिस्ट। वीडियो YouTube से चलते हैं; चलाने के लिए टैप करें।')}</div><div class="vf" id="vfeed">${vFeed()}</div>`;
