function vEnd(i,box){const c=VIDS[i].cat,o=VIDS.map((_,j)=>j).filter(j=>j!==i),n=[...o.filter(j=>VIDS[j].cat===c&&(j>i)),...o.filter(j=>VIDS[j].cat===c&&j<i),...o.filter(j=>VIDS[j].cat!==c)].slice(0,2);box.innerHTML=`<div class="vx"><b>${t('Watch next','अगला देखें')}</b>${n.map(j=>`<button data-nx="${j}">▶ ${esc(VIDS[j].title.slice(0,60))}</button>`).join('')}<button data-rp="${i}">↺ ${t('Replay','दोबारा')}</button></div>`;box.querySelectorAll('[data-nx]').forEach(b=>b.onclick=e=>{e.stopPropagation();const j=+b.dataset.nx;if(!document.getElementById('vc'+j)){VCAT='all';M.querySelectorAll('[data-vc]').forEach(x=>x.classList.toggle('on',x.dataset.vc==='all'));document.getElementById('vfeed').innerHTML=vFeed();vBind()}document.getElementById('vc'+j).scrollIntoView({behavior:'smooth',block:'center'});vPlay(j)});box.querySelector('[data-rp]').onclick=e=>{e.stopPropagation();vPlay(i)}}
function vPlay(i){Object.keys(PLAY).forEach(k=>{if(+k!==i&&PLAY[k]&&PLAY[k].pauseVideo)try{PLAY[k].pauseVideo()}catch(_){}});const box=M.querySelector(`[data-vi="${i}"]`);if(!box)return;const id=VIDS[i].id;box.onclick=null;box.innerHTML=`<iframe id="yt${i}" src="https://www.youtube-nocookie.com/embed/${id}?rel=0&modestbranding=1&playsinline=1&enablejsapi=1&origin=${encodeURIComponent(location.origin)}" title="${esc(VIDS[i].title)}" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen></iframe>`;ytApi().then(()=>{if(!(window.YT&&YT.Player))return;PLAY[i]=new YT.Player('yt'+i,{events:{onStateChange:e=>{if(e.data===0){try{PLAY[i].destroy()}catch(_){}delete PLAY[i];vEnd(i,box)}}}})})}
